import type React from "react"
import type { Metadata } from "next"
import { Inter, JetBrains_Mono } from "next/font/google"
import { Analytics } from "@vercel/analytics/next"
import "./globals.css"
import { ThemeProvider } from "@/components/theme-provider"
import { Header } from "@/components/header"

const inter = Inter({ subsets: ["latin"] })
const jetbrainsMono = JetBrains_Mono({ subsets: ["latin"], variable: "--font-mono" })

export const metadata: Metadata = {
  title: "Aman Kumar Labh | Flutter Developer & Fullstack Engineer",
  description:
    "Full-stack developer, CS student, and AI automation specialist. Building Artyug and consulting for startups.",
  generator: "v0.app",
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en" suppressHydrationWarning>
      <body className={`${inter.className} ${jetbrainsMono.variable} antialiased`}>
        <ThemeProvider
          attribute="class"
          defaultTheme="light"
          enableSystem={false}
          disableTransitionOnChange
        >
          <Header />
          <main className="min-h-[calc(100vh-3.5rem)]">
            {children}
          </main>
          <Analytics />
        </ThemeProvider>
      </body>
    </html>
  )
}
"use client"

import { Github, ExternalLink, Mail, Linkedin, Twitter, MessageSquare } from "lucide-react"
import { useEffect, useState } from "react"
import GitHubStats from "@/components/github-stats"
import WorkExperience from "@/components/work-experience"
import NotesSection from "@/components/notes-section"
import FeedbackSection from "@/components/feedback-section"
import ChatContainer from "@/components/chat-container"
import { StatusSection } from "@/components/status-section"
import { BlogHomeSection } from "@/components/blog-home-section"
import { DoodleDinoGame } from "@/components/doodle-dino-game"

export default function Home() {
  const [terminalText, setTerminalText] = useState("")
  const fullText = "For work inquiries, email me at [redacted]"

  useEffect(() => {
    let index = 0
    const timer = setInterval(() => {
      if (index <= fullText.length) {
        setTerminalText(fullText.slice(0, index))
        index++
      } else {
        clearInterval(timer)
      }
    }, 50)
    return () => clearInterval(timer)
  }, [])

  return (
    <main className="relative min-h-screen bg-background overflow-x-hidden">
      {/* 3D Grid Background */}
      <div className="pointer-events-none fixed inset-0 overflow-hidden">
        <div
          className="absolute inset-0"
          style={{
            backgroundImage: `
              linear-gradient(to right, var(--grid-color) 1px, transparent 1px),
              linear-gradient(to bottom, var(--grid-color) 1px, transparent 1px)
            `,
            backgroundSize: "60px 60px",
          }}
        />
        <div
          className="absolute inset-0"
          style={{
            background: `
              radial-gradient(ellipse at 50% 0%, transparent 0%, var(--background) 70%),
              linear-gradient(to bottom, transparent 0%, var(--background) 100%)
            `,
          }}
        />
        <div
          className="absolute bottom-0 left-0 right-0 h-[60vh]"
          style={{
            background: "linear-gradient(to top, var(--background) 0%, transparent 100%)",
            transform: "perspective(500px) rotateX(60deg)",
            transformOrigin: "bottom center",
          }}
        >
          <div
            className="absolute inset-0"
            style={{
              backgroundImage: `
                linear-gradient(to right, var(--grid-color) 1px, transparent 1px),
                linear-gradient(to bottom, var(--grid-color) 2px, transparent 2px)
              `,
              backgroundSize: "80px 40px",
            }}
          />
        </div>
        <div
          className="absolute inset-0 opacity-30"
          style={{
            backgroundImage: "radial-gradient(var(--grid-color) 1px, transparent 1px)",
            backgroundSize: "20px 20px",
          }}
        />
      </div>

      <DoodleDinoGame />

      {/* Content */}
      <div className="relative z-10 mx-auto max-w-5xl px-6 py-16 md:py-24">
        <header className="mb-16">
          <div className="mb-6 inline-block rounded border border-border bg-card/80 backdrop-blur-sm px-3 py-1 font-mono text-sm text-muted-foreground">
            ~/aman-kumar
          </div>
          <h1 className="mb-2 text-4xl font-bold tracking-tight text-foreground md:text-5xl">Aman Kumar Labh</h1>
