"use client"

import { useEffect, useRef } from "react"

// ponytail: raw WebGL fullscreen shader, no three.js — swap to R3F only if the scene needs real 3D objects
const vert = `
attribute vec2 a;
void main() { gl_Position = vec4(a, 0.0, 1.0); }
`

const frag = `
precision highp float;
uniform vec2 res;
uniform float t;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }

float stars(vec2 p, float scale) {
  vec2 g = p * scale;
  vec2 id = floor(g);
  vec2 f = fract(g) - 0.5;
  float h = hash(id);
  if (h < 0.965) return 0.0;
  vec2 o = vec2(hash(id + 1.3), hash(id + 7.1)) - 0.5;
  float d = length(f - o * 0.7);
  float tw = 0.6 + 0.4 * sin(t * 2.0 + h * 50.0);
  return smoothstep(0.08, 0.0, d) * tw;
}

float disk(vec2 d, float rs) {
  float r = length(d);
  float a = atan(d.y, d.x);
  float band = smoothstep(rs * 1.4, rs * 1.9, r) * smoothstep(rs * 5.5, rs * 2.2, r);
  float swirl = a + t * 0.35 / max(r, 0.05);
  float streaks = 0.55 + 0.45 * sin(swirl * 3.0 + r * 40.0) * sin(swirl * 7.0 - r * 65.0);
  float doppler = 1.0 + 0.7 * (d.x / max(r, 1e-3));
  return band * streaks * doppler;
}

void main() {
  vec2 p = (gl_FragCoord.xy - 0.5 * res) / res.y;
  float rs = 0.11;
  float r = length(p);
  vec2 dir = p / max(r, 1e-4);

  // gravitational lensing: bend background toward the hole
  vec2 q = p - dir * (rs * rs * 1.6 / max(r, rs));
  float s = stars(q, 90.0) + stars(q + 3.7, 45.0) * 0.6;
  vec3 col = vec3(s);

  // lensed far side of the disk wraps around the hole
  float halo = smoothstep(rs * 1.05, rs * 1.25, r) * smoothstep(rs * 2.6, rs * 1.35, r);
  float haloSwirl = 0.6 + 0.4 * sin(atan(p.y, p.x) * 5.0 - t * 0.8);
  col += vec3(0.85, 0.82, 0.78) * halo * haloSwirl * (0.55 + 0.45 * dir.y) * 0.9;

  // photon ring
  col += vec3(1.0) * exp(-pow((r - rs * 1.08) / 0.004, 2.0)) * 0.9;

  // event horizon
  col *= smoothstep(rs, rs * 1.03, r);

  // tilted accretion disk; back half hidden behind the horizon
  vec2 dd = vec2(p.x, p.y * 4.5);
  float dv = disk(dd, rs);
  if (p.y > 0.0 && r < rs * 1.03) dv = 0.0;
  col += vec3(0.95, 0.9, 0.85) * dv * 0.85;

  // dim edges so foreground text stays readable
  col *= 0.75 * smoothstep(1.3, 0.2, r);
  gl_FragColor = vec4(col, 1.0);
}
`

export function BlackHole() {
  const ref = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    const canvas = ref.current
    const gl = canvas?.getContext("webgl")
    if (!canvas || !gl) return

    const compile = (type: number, src: string) => {
      const s = gl.createShader(type)!
      gl.shaderSource(s, src)
      gl.compileShader(s)
      return s
    }
    const prog = gl.createProgram()!
    gl.attachShader(prog, compile(gl.VERTEX_SHADER, vert))
    gl.attachShader(prog, compile(gl.FRAGMENT_SHADER, frag))
    gl.linkProgram(prog)
    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) return
    gl.useProgram(prog)

