p='components/theme-toggle.tsx'
s=open(p).read()
reps=[
("import * as React from 'react'\n","import * as React from 'react'\nimport { flushSync } from 'react-dom'\n"),
('''  const { setTheme } = useTheme()
''','''  const { setTheme, resolvedTheme } = useTheme()

  // dark mode bursts out of the black hole at screen center; light mode collapses back into it
  const switchTheme = (theme: string) => {
    const toDark = theme === 'dark' || (theme === 'system' && matchMedia('(prefers-color-scheme: dark)').matches)
