    if (!document.startViewTransition || reduced || toDark === (resolvedTheme === 'dark')) return setTheme(theme)
    const root = document.documentElement
    root.dataset.vt = toDark ? 'in' : 'out'
    document
      .startViewTransition(() => flushSync(() => setTheme(theme)))
      .finished.finally(() => delete root.dataset.vt)
  }
'''),
('onClick={() => setTheme("light")}','onClick={() => switchTheme("light")}'),
('onClick={() => setTheme("dark")}','onClick={() => switchTheme("dark")}'),
('onClick={() => setTheme("system")}','onClick={() => switchTheme("system")}'),
]
for a,b in reps:
    assert s.count(a)==1,a
    s=s.replace(a,b)
open(p,'w').write(s)

open('app/globals.css','a').write('''
