::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}
html[data-vt="in"]::view-transition-new(root) {
  animation: bh-open 1.1s cubic-bezier(0.7, 0, 0.3, 1);
}
html[data-vt="out"]::view-transition-old(root) {
  z-index: 1;
  animation: bh-close 1.1s cubic-bezier(0.7, 0, 0.3, 1) forwards;
}
@keyframes bh-open {
  from { clip-path: circle(0% at 50% 50%); }
  to { clip-path: circle(150% at 50% 50%); }
}
@keyframes bh-close {
  from { clip-path: circle(150% at 50% 50%); }
  to { clip-path: circle(0% at 50% 50%); }
}
''')
EOF
