  c = mix(c, vec3(0.85, 0.9, 1.0), clamp(temp - 1.0, 0.0, 1.0));
  float I = pow(D, 3.0) * pow(DISK_IN / r, 1.4) * 2.5;
  return vec4(c * I, dens);
